"use client";

import { loadFont as loadSans } from "@remotion/google-fonts/Inter";
import type React from "react";
import {
  AbsoluteFill,
  Easing,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { Odometer } from "@/registry/snap-cn/counter";

// Load Inter inside the composition so headless renders don't fall back to
// the default sans-serif (see github-stars for the rationale).
const { fontFamily: FONT_FAMILY } = loadSans("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});

/** Product Hunt's native upvote orange — platform chrome, arrow only. */
export const PH_ORANGE = "#FF6154";

export type BadgePosition =
  | "top-left"
  | "top-right"
  | "bottom-left"
  | "bottom-right"
  | "center";

export interface ProductHuntBadgeProps {
  /** Headline of the badge. */
  tagline?: string;
  /** Upvote count the odometer starts from. */
  upvotesFrom?: number;
  /** Upvote count the odometer locks on. */
  upvotesTo?: number;
  /** Optional rank caption, e.g. "#1 Product of the Day". */
  rank?: string;
  /** Frame at which the upvote arrow is pressed (4-frame dip, then release). */
  pressAt?: number;
  /** Corner preset for end-card placement. */
  position?: BadgePosition;
  /** Inset from the canvas edges for the corner presets, in px. */
  margin?: number;
  /** Product Hunt's native orange. Kept for the arrow only — change sparingly. */
  arrowColor?: string;
  theme?: "light" | "dark";
  /** Uniform badge scale — bump for 4K canvases or hero placements. */
  scale?: number;
  /** Portion of the composition spent counting; the rest holds the target. */
  countPortion?: number;
  /** Show the pulsing "live" dot before the tagline. */
  liveDot?: boolean;
  speed?: number;
}

interface Theme {
  bg: string;
  bgSubtle: string;
  border: string;
  fg: string;
  fgMuted: string;
  shadow: string;
}

// snap-cn design tokens: light-first, hairline borders, muted grays.
const THEMES: Record<"light" | "dark", Theme> = {
  light: {
    bg: "#FFFFFF",
    bgSubtle: "#F2F4F7",
    border: "#E4E7EC",
    fg: "#101828",
    fgMuted: "#667085",
    shadow:
      "0 1px 2px rgba(16, 24, 40, 0.05), 0 8px 24px -12px rgba(16, 24, 40, 0.08)",
  },
  dark: {
    bg: "#141417",
    bgSubtle: "#1D1D21",
    border: "#26272B",
    fg: "#FAFAFA",
    fgMuted: "#A1A1AA",
    shadow: "0 1px 2px rgba(0, 0, 0, 0.4), 0 8px 24px -12px rgba(0, 0, 0, 0.5)",
  },
};

const COUNT_START_FRAME = 12;
const COUNT_EASING = Easing.bezier(0.5, 1, 0.5, 1);
export const PRESS_DIP_FRAMES = 4;
export const PRESS_RECOVER_FRAMES = 10;

// --- Pure helpers (unit-tested) -------------------------------------------

/** Absolute-position style for a corner preset. Pure — no viewport access. */
export function badgeAnchor(
  position: BadgePosition,
  margin: number,
): React.CSSProperties {
  switch (position) {
    case "top-left":
      return { left: margin, top: margin };
    case "top-right":
      return { right: margin, top: margin };
    case "bottom-left":
      return { left: margin, bottom: margin };
    case "center":
      return { left: "50%", top: "50%", transform: "translate(-50%, -50%)" };
    default:
      return { right: margin, bottom: margin };
  }
}

/**
 * Monotonic 0→1 counter ramp. Starts after the entrance settles
 * (COUNT_START_FRAME) and locks at `durationInFrames * countPortion`.
 * Must stay monotonic — it drives the odometer wheels.
 */
export function computeCountProgress({
  frame,
  speed = 1,
  durationInFrames,
  countPortion = 0.8,
}: {
  frame: number;
  speed?: number;
  durationInFrames: number;
  countPortion?: number;
}): number {
  const portion = Math.min(1, Math.max(0.05, countPortion));
  const lockFrame = Math.max(COUNT_START_FRAME + 1, durationInFrames * portion);
  return interpolate(frame * speed, [COUNT_START_FRAME, lockFrame], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: COUNT_EASING,
  });
}

/** Continuous upvote value for a given progress — from → to, then locked. */
export function upvoteValue(
  progress: number,
  from: number,
  to: number,
): number {
  const start = Math.max(0, from);
  const end = Math.max(0, to);
  return start + Math.min(1, Math.max(0, progress)) * (end - start);
}

export interface PressBump {
  /** 0→1→0 dip amount: 1 at the bottom of the 4-frame dip. */
  dip: number;
  /** Whether the press has bottomed out (arrow released). */
  pressed: boolean;
}

/**
 * The upvote-arrow press: a 4-frame dip down, then a fast ease-out release.
 * Pure — feed `frame * speed` and the press frame.
 */
export function pressBump(
  frame: number,
  pressAt: number,
  dipFrames = PRESS_DIP_FRAMES,
  recoverFrames = PRESS_RECOVER_FRAMES,
): PressBump {
  const dip = interpolate(
    frame,
    [pressAt, pressAt + dipFrames, pressAt + dipFrames + recoverFrames],
    [0, 1, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.quad),
    },
  );
  return { dip, pressed: frame >= pressAt + dipFrames };
}

/** Fading wash on the upvote button right after the press (0→1→0). */
export function pressWash(
  frame: number,
  pressAt: number,
  dipFrames = PRESS_DIP_FRAMES,
): number {
  return interpolate(
    frame,
    [pressAt, pressAt + dipFrames, pressAt + dipFrames + 18],
    [0, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" },
  );
}

/** Gentle 0.55→1 opacity pulse for the live dot. Period ~45 frames at 30fps. */
export function liveDotPulse(frame: number, period = 45): number {
  const t = (Math.sin((frame / period) * Math.PI * 2) + 1) / 2;
  return 0.55 + 0.45 * t;
}

// --- Sub-components --------------------------------------------------------

function UpvoteArrow({ size, fill }: { size: number; fill: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill={fill}
      stroke={fill}
      strokeWidth={3}
      strokeLinejoin="round"
    >
      <title>Upvote</title>
      <path d="M12 5.5 L20 18.5 H4 Z" />
    </svg>
  );
}

// --- Main composition ------------------------------------------------------

export function ProductHuntBadge({
  tagline = "Live on Product Hunt",
  upvotesFrom = 480,
  upvotesTo = 612,
  rank = "#1 Product of the Day",
  pressAt = 45,
  position = "bottom-right",
  margin = 48,
  arrowColor = PH_ORANGE,
  theme = "light",
  scale = 1,
  countPortion = 0.8,
  liveDot = true,
  speed = 1,
}: ProductHuntBadgeProps) {
  const frame = useCurrentFrame();
  const { fps, durationInFrames } = useVideoConfig();
  const t = THEMES[theme] ?? THEMES.light;
  const localFrame = frame * speed;

  // Entrance: high-damping spring — fast, subtle settle, no bounce on chrome.
  const enter = spring({
    fps,
    frame: localFrame,
    config: { damping: 200, stiffness: 170, mass: 0.8 },
  });
  const enterY = interpolate(enter, [0, 1], [16, 0]);
  const enterScale = interpolate(enter, [0, 1], [0.96, 1]);

  // Count-up: monotonic ramp into the continuous odometer.
  const progress = computeCountProgress({
    frame,
    speed,
    durationInFrames,
    countPortion,
  });
  const current = upvoteValue(progress, upvotesFrom, upvotesTo);

  // Arrow press: 4-frame dip, fast release.
  const bump = pressBump(localFrame, pressAt);
  const arrowY = bump.dip * 3;
  const arrowScale = 1 - bump.dip * 0.14;
  const wash = pressWash(localFrame, pressAt);

  const anchor = badgeAnchor(position, margin);

  return (
    <AbsoluteFill style={{ background: "transparent" }}>
      <div style={{ position: "absolute", ...anchor }}>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 20,
            padding: "16px 18px 16px 22px",
            background: t.bg,
            border: `1px solid ${t.border}`,
            borderRadius: 10,
            boxShadow: t.shadow,
            opacity: enter,
            transform: `translateY(${enterY}px) scale(${enterScale * scale})`,
            transformOrigin:
              position === "center"
                ? "center"
                : `${position.includes("left") ? "left" : "right"} ${
                    position.includes("top") ? "top" : "bottom"
                  }`,
            fontFamily: FONT_FAMILY,
          }}
        >
          <div style={{ display: "flex", flexDirection: "column", gap: 3 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              {liveDot && (
                <span
                  style={{
                    width: 9,
                    height: 9,
                    borderRadius: 9999,
                    background: "#12B76A",
                    opacity: liveDotPulse(localFrame),
                    flexShrink: 0,
                  }}
                />
              )}
              <span
                style={{
                  fontSize: 21,
                  fontWeight: 600,
                  color: t.fg,
                  letterSpacing: "-0.01em",
                  lineHeight: 1.2,
                  whiteSpace: "nowrap",
                }}
              >
                {tagline}
              </span>
            </div>
            {rank ? (
              <span
                style={{
                  fontSize: 15,
                  fontWeight: 500,
                  color: t.fgMuted,
                  lineHeight: 1.3,
                  whiteSpace: "nowrap",
                  paddingLeft: liveDot ? 19 : 0,
                }}
              >
                {rank}
              </span>
            ) : null}
          </div>

          <div
            style={{
              position: "relative",
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              gap: 2,
              padding: "10px 16px 8px",
              borderRadius: 8,
              border: `1px solid ${t.border}`,
              background: t.bg,
              overflow: "hidden",
              flexShrink: 0,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: t.bgSubtle,
                opacity: wash,
              }}
            />
            <div
              style={{
                position: "relative",
                transform: `translateY(${arrowY}px) scale(${arrowScale})`,
                display: "flex",
              }}
            >
              <UpvoteArrow size={22} fill={arrowColor} />
            </div>
            <div style={{ position: "relative" }}>
              <Odometer current={current} fontSize={21} color={t.fg} />
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
